let sizer = 0
let speed = 0.3;
function setup() {
  createCanvas(400, 400);
  noStroke();


}

function draw() {
  background(0,30);
	fill(255,150)
  let t = millis()/1000;
  for(let i = 25; i > 0; i--){
    let a = t+i/8
           rect(min(395,max(0,200+sizer*sin(a)+random(100)*sin(t/3))),min(395,max(0,200+sizer*cos(a)+200*cos(t/3))),5,5);
  }
  sizer+=speed;
  if(sizer < 0 || sizer > 200){
    speed *= -1;
  }

}


